import marimo

__generated_with = "0.11.8"
app = marimo.App(width="full", app_title="Deadman")


@app.cell(hide_code=True)
def _():
    import marimo as mo

    # different health levels have different faces
    faces_urls = [
        "data:image/bmp;base64,",
        "data:image/bmp;base64,",
        "data:image/bmp;base64,",
        "data:image/bmp;base64,",
        "data:image/bmp;base64,",
        "data:image/bmp;base64,",
        "data:image/bmp;base64,",
        "data:image/bmp;base64,",
    ]
    faces_urls.reverse()
    return faces_urls, mo


@app.cell
def _():
    import time

    import github  # game model based on PyGithub
    from plotly import graph_objects as go


    class Game(github.Github):
        def __init__(self):
            # raise exceptions instead of retry
            super().__init__(retry=None)

        def consume_core(self) -> None:
            """Consumes 1 core resource.

            Raises RateLimitExceededException if core limit reached.
            """
            # request to /get_hooks returns 404, but counts towards rate limit
            try:
                self.get_hooks()
            except github.UnknownObjectException as e:
                return e

        def consume_search(self) -> None:
            """Consumes 1 search resource.

            Raises RateLimitExceededException if search limit reached.
            """
            # search request without query returns 422 validation error, but counts towards rate limit
            try:
                self.requester.requestJsonAndCheck("GET", "/search/users")
            except github.GithubException as e:
                if e._GithubException__status != 422:
                    raise  # raise all other errors e.g. ratelimitexceeded
                return e

        def consume_integration_manifest(self) -> None:
            """Consumes 1 integration_manifest resource.

            Raises RateLimitExceededException if core limit reached.
            """
            # request with bullshit code returns 404, but counts towards rate limit
            try:
                self.requester.requestJsonAndCheck(
                    "POST", "/app-manifests/{code}/conversions"
                )
            except github.UnknownObjectException as e:
                return e


    class DeadManGame(Game):
        def __init__(self):
            super().__init__()
            self.refresh()
            self.ammo_prev = 0

        def refresh(self):
            rate_limit = self.get_rate_limit()
            self.clip_size = rate_limit.core.limit
            self.health = rate_limit.search.remaining / rate_limit.search.limit
            self.ammo = rate_limit.core.remaining
            self.time_until_alive = int(rate_limit.search.reset.timestamp() - time.time())

        def attack(self):
            try:
                self.consume_core()  # ammo -> search resource
                self.consume_search()  # health -> core resource
            except github.RateLimitExceededException:
                pass  # no more ammo/health
            self.refresh()
            self.ammo_prev = self.ammo


    game = DeadManGame()
    return DeadManGame, Game, game, github, go, time


@app.cell
def _(mo):
    # ui buttons
    attack = mo.ui.run_button(kind="danger", label="Attack! 💥")
    refresh = mo.ui.refresh()
    return attack, refresh


@app.cell
def _(attack, faces_urls, game, go, mo, refresh):
    # handle button clicks
    if attack.value:
        game.attack()

    if refresh.value:
        game.refresh()

    # selct face based on health
    face_url = faces_urls[int(game.health * (len(faces_urls) - 1) + 0.5)]

    fig = go.Figure(
        go.Indicator(
            mode="number+gauge+delta",
            gauge={
                "shape": "bullet",
                "axis": {
                    "visible": False,
                    "range": [0, game.clip_size],
                },
            },
            value=game.ammo,
            delta={"reference": game.ammo_prev},
            number={"suffix": "💣"},
        ),
        layout=dict(height=220, width=400),
    )

    mo.vstack(
        [
            mo.md("# You alive man." if game.health else "# You adead man!"),
            mo.image(
                face_url,
                width="20em",
                rounded=True,
                style={"image-rendering": "pixelated"},
                caption=f"You.<br><small>Status: {'alive.' if game.health else 'adead.'}</small>",
            ),
            mo.md(
                f"""
                /// warning | You cannot play

                You adead man. Only alive man play.

                {refresh} Please wait {game.time_until_alive} seconds to be alive man.
                ///
                """
            )
            if not game.health
            else "",
            mo.hstack(
                [mo.as_html(fig), attack],
                # justify="space-around",
                align="center",
            ),
            mo.md(
                f"""
                /// warning | You cannot attack

                You have no ammo man.

                <small>
                (But you can find more ammo using a different IP address.
                Because that's how ammo works in this game.
                It's _IP address ammo_.)
                </small>
                ///
                """
            )
            if not game.ammo
            else "",
        ],
        align="center",
    )
    return face_url, fig


if __name__ == "__main__":
    app.run()
